insert into productos (id, nombre, cat, marca, precio, antes, desde, pres, descripcion, puntos, opciones, fotos, wa, destacado, disponible, orden) values
('ovoprotein960', 'OvoProtein Albúmina de huevo 960 g', 'proteina', 'OvoProtein', 320, null, false, '960 g', 'Suplemento alimenticio en polvo a base de albúmina de huevo, industria boliviana. 960 g, 32 servicios de 30 g. Proteína de fácil digestión, sin pesadez ni hinchazón.', array['Cerca de 90% de proteína: unos 27 g por servicio','Sabores: 60% albúmina de huevo, 20% colágeno hidrolizado y 20% whey. Neutra: 100% albúmina','Contiene los 9 aminoácidos esenciales','0% azúcares refinados, bajo en carbohidratos y en grasas','Libre de gluten y de lactosa, ideal para todas las edades','Unas 114 kcal por servicio']::text[], array['Frutilla','Chocolate','Vainilla','Neutra']::text[], array['img/productos/ovoproteinfrutilla960.webp','img/productos/ovoproteinchocolate960.webp','img/productos/ovoproteinvainilla960.webp','img/productos/ovoproteinneutra960.webp']::text[], '', true, true, 0),
('ovoprotein480', 'OvoProtein Albúmina de huevo 480 g', 'proteina', 'OvoProtein', 170, null, false, '480 g', 'La misma proteína a base de albúmina de huevo en sobre de 480 g, para probarla o llevarla contigo. Industria boliviana.', array['Cerca de 90% de proteína: unos 27 g por servicio','60% albúmina de huevo, 20% colágeno hidrolizado y 20% whey','Contiene los 9 aminoácidos esenciales','0% azúcares refinados, libre de gluten y de lactosa']::text[], array['Frutilla','Chocolate']::text[], array['img/productos/ovoproteinfrutilla480.webp','img/productos/ovoproteinchocolate480.webp']::text[], '', true, true, 1),
('ovobarra', 'Barra proteica OvoProtein 30 g', 'snacks', 'OvoProtein', 15, null, false, '30 g', 'Barra proteica a base de albúmina de huevo, colágeno hidrolizado, proteína aislada de soya y leche entera. Energía para llevar a donde vayas.', array['10,1 g de proteína por barra','16,2 g de carbohidratos y 8,6 g de azúcares','Contiene los 9 aminoácidos esenciales','Sabores chocolate y frutilla']::text[], array['Chocolate','Frutilla']::text[], array['img/productos/ovobarrachocolate.webp','img/productos/ovobarrafrutilla.webp']::text[], '', false, true, 2),
('ovocreatina300', 'Creatina Monohidratada Ultra Micronizada 300 g', 'creatina', 'OvoProt', 280, null, false, '300 g', 'Suplemento alimenticio en polvo a base de creatina monohidratada ultra micronizada. Industria boliviana. Solo 5 g al día.', array['Pureza farmacéutica de 99,5% o más','5 g diarios, cero excusas','Ultra micronizada para mezclarse mejor','Contenido neto de 300 g']::text[], array[]::text[], array['img/productos/ovocreatina300.webp']::text[], '', true, true, 3)
