-- Productos reales de OVO (catálogo oficial) y combos de arranque
delete from productos where id in ('ovofrutilla960','ovochocolate960','ovovainilla960','ovoneutro960','ovofrutilla480');
on conflict (id) do update set nombre=excluded.nombre, precio=excluded.precio, descripcion=excluded.descripcion, puntos=excluded.puntos, opciones=excluded.opciones, fotos=excluded.fotos;

on conflict (id) do nothing;
